// Builds the self-hosted basemap style from the resolved --map-* palette.
//
// The geometry is Natural Earth (public domain), generated by
// scripts/build-basemap.sh and served as static GeoJSON. At the zoom levels the
// globe uses, the whole dataset is under 100 KB gzipped, so tiling it would add
// moving parts for no benefit. See the script header for when that changes.

const LAND_URL = '/static/geo/world-land-v1.json'
const GRATICULE_URL = '/static/geo/world-graticule-v1.json'

export const ATTRIBUTION = '<a href="https://www.naturalearthdata.com/" target="_blank" rel="noreferrer">Natural Earth</a>'

// layerId -> [paint property, palette key]. Also drives repaint(), so a layer
// added here is themed automatically.
export const PAINT_BINDINGS = [
  ['basemap-ocean', 'background-color', 'ocean'],
  ['basemap-land', 'fill-color', 'land'],
  ['basemap-boundary', 'line-color', 'boundary'],
  ['basemap-graticule', 'line-color', 'graticule'],
  // Data layers added imperatively after load. Absent layers are skipped, so
  // listing them here is safe on maps that never create them.
  ['globe-arcs-line', 'line-color', 'arc-ok'],
  ['globe-hubs-dot', 'circle-color', 'hub'],
]

export function buildStyle(palette) {
  return {
    version: 8,
    // No glyphs or sprite: this style has no symbol layers. Layers that need
    // labels (hub and flight callsigns) add their own glyph source.
    sources: {
      'ne-land': { type: 'geojson', data: LAND_URL, attribution: ATTRIBUTION },
      'ne-graticule': { type: 'geojson', data: GRATICULE_URL },
    },
    layers: [
      {
        id: 'basemap-ocean',
        type: 'background',
        paint: { 'background-color': palette.ocean },
      },
      {
        id: 'basemap-graticule',
        type: 'line',
        source: 'ne-graticule',
        paint: {
          'line-color': palette.graticule,
          'line-width': 0.5,
          'line-opacity': ['interpolate', ['linear'], ['zoom'], 0, 0.5, 4, 0.25, 6, 0],
        },
      },
      {
        id: 'basemap-land',
        type: 'fill',
        source: 'ne-land',
        paint: { 'fill-color': palette.land },
      },
      {
        id: 'basemap-boundary',
        type: 'line',
        source: 'ne-land',
        paint: {
          'line-color': palette.boundary,
          'line-width': ['interpolate', ['linear'], ['zoom'], 0, 0.4, 4, 0.8, 8, 1.2],
          'line-opacity': 0.9,
        },
      },
    ],
  }
}

export function skySpec(palette) {
  return {
    'sky-color': palette.ocean,
    'horizon-color': palette.atmosphere,
    'fog-color': palette.atmosphere,
    'horizon-fog-blend': 0.6,
    'atmosphere-blend': ['interpolate', ['linear'], ['zoom'], 0, 1, 6, 1, 8, 0],
  }
}

// Repaints in place on theme change.
//
// Deliberately NOT map.setStyle(): that tears down and rebuilds the style,
// destroying the arc/hub/flight layers added imperatively after load. Setting
// paint properties is instant, flicker-free and preserves all of that state.
export function repaint(map, palette) {
  if (!map || !map.getLayer) return
  for (const [layerId, property, key] of PAINT_BINDINGS) {
    if (map.getLayer(layerId)) map.setPaintProperty(layerId, property, palette[key])
  }
  if (typeof map.setSky === 'function') {
    try {
      map.setSky(skySpec(palette))
    } catch {
      // Sky is decorative; an older renderer refusing the spec is not fatal.
    }
  }
}
